/* Script library expansion (talk2.js) — P31–P100: Realtor bridge, escrow deadlines, ISA desk, equity, reverse, refi, niches, partners, military, AI team, past clients */
SCRIPTS.push(
SP("P31","Realtor bridge","Steven's own buyer client → mortgage side (consent + dual-role disclosure)",{when:"Buyer represented by Steven through LPT Realty asks about financing",goal:"Get written consent to share file data, deliver the affiliated/dual-role disclosure, and make clear the buyer is free to choose any lender",script:"{{FIRST}}, quick housekeeping before we talk money. As you know, I'm your agent through LPT Realty, and I'm also a licensed mortgage loan originator with Patriot Pacific Financial. That means I could help you on both sides — but you are never required to use me for the loan.\nHere's what I'll send you today: a written disclosure that explains both roles and how I'm paid on each side, plus a consent form so my real estate file and my mortgage file can share your information. Nothing moves until you sign it.\nI'd also encourage you to get at least one other Loan Estimate. If someone beats our terms, take it — I'll still be your agent and I'll still fight for you on the house. Fair?",objections:[["Isn't that a conflict of interest?","Fair question — that's exactly why it's disclosed in writing. You see how I'm paid on both sides, you can compare with any lender, and nothing about my representation changes based on who you choose."],["Can you just give me a better deal since you're my agent?","I can't trade a discount on one side for the business on the other — that's not allowed. What I can do is show you today's pricing in writing, with the disclosures, and let you compare it straight up."],["Do I really need another quote?","You don't have to, but I recommend it. Comparing Loan Estimates line by line is the best way to know you're getting a fair deal."]],next:"Send dual-role/affiliated disclosure + info-sharing consent for e-signature; Zoho tag 'RE-to-MLO consent'; when signed, move card on Handoff Board to Mortgage intake",compliance:"Have compliance confirm whether a formal RESPA Affiliated Business Arrangement disclosure applies (it depends on ownership interests) and deliver any state dual-capacity disclosure (CA DRE/DFPI) at or before the referral. No requirement to use the affiliate; no fee or discount for the referral itself; compensation only for services actually performed. Steven Shearrill NMLS #____."}),
SP("P32","Realtor bridge","Partner agent asks for a pre-approval status update",{when:"Realtor partner calls or texts asking 'where are we on my buyer?'",goal:"Give a useful update without oversharing private financial data; keep the agent confident",script:"Hi {{FIRST}}, it's {{AGENT}} on Steven Shearrill's team at Patriot Pacific. Thanks for checking in on {{CLIENT}}.\nHere's what I can share with their permission: the file is in {{STAGE}} — we have {{RECEIVED}} and we're waiting on {{OUTSTANDING}}. Steven expects to issue the updated approval letter by {{DATE}} once those come in.\nWhat I can't share are the specifics of their credit or income — but if anything puts the purchase price or the timeline at risk, Steven will call you himself the same day. Is there an offer brewing I should know about so we can prioritize?",objections:[["Just tell me what they qualify for","I can confirm the price range the approval letter will support, and we'll tailor the letter to each offer. The underlying details belong to the buyer, so I'll leave those to them."],["Why is it taking so long?","We're waiting on {{OUTSTANDING}}. If you have a good line to the buyer, a nudge from you helps — and I'll text them the checklist again right now."],["Can you send me the full file?","I can't send their documents, but I'll send a status summary any time you ask, and Steven is available for a three-way call with the buyer."]],next:"Log update on Handoff Board; send partner status text from approved template; set Speed-to-Lead reminder for outstanding docs",compliance:"GLBA/privacy: share only what the borrower authorized; no credit scores, income, or debts to third parties without written consent. No approval guarantees — approval is subject to underwriting."}),
SP("P33","Realtor bridge","Co-marketing a listing with a partner agent (RESPA §8)",{when:"Agent proposes a joint flyer, ad, or social campaign on a listing",goal:"Say yes to compliant co-marketing; split costs by actual use; avoid anything of value for referrals",script:"Love the idea, {{FIRST}}. Here's how Steven keeps co-marketing clean so it protects both of us:\n1) We split the cost based on how much of the piece each of us actually uses — if my info takes a quarter of the flyer, I pay a quarter of the cost, and we put that in a short written agreement.\n2) I pay the vendor or you directly for my share — no comped ads, no free leads in exchange for sending buyers my way.\n3) Both our disclosures go on it: your brokerage info, plus Patriot Pacific Financial, NMLS #____, Equal Housing Opportunity, and no rates or payments unless the full disclosure is included.\nIf that works, send me the draft and the invoice, and I'll get compliance to sign off within a day or two.",objections:[["Can't you just cover the whole thing? I send you all my buyers.","I can't — paying more than my share would look like a payment for referrals, and that's a RESPA problem for both of us. A fair split keeps us both in business."],["Let's put a teaser rate on it to drive calls","Rates trigger full advertising disclosures and they change daily. Let's lead with the property and offer a 'get your numbers' call instead."],["Do we really need a written agreement?","It's one page and it's our proof that each of us paid fair value for what we used. It protects you as much as me."]],next:"Create co-marketing agreement (proportional split) and route piece to compliance; Zoho tag 'Co-marketing'; log costs in Broker Bridge",compliance:"RESPA §8: no thing of value for referrals; each party pays its proportional share based on actual use at fair market value; keep agreement and invoices. Advertising must include NMLS #____ and EHO; any rate/payment requires Reg Z trigger-term disclosures."}),
SP("P34","Realtor bridge","Open-house lender table",{when:"Partner hosts an open house and invites Steven's team",goal:"Help visitors understand financing; capture leads with consent; stay within RESPA",script:"(to visitor) Hi, I'm {{AGENT}} with Steven Shearrill's team at Patriot Pacific Financial — I'm just here to answer financing questions while you look around. Any questions about down payment, VA or FHA, or what a home like this might cost each month?\n… I can't give you a payment on this house without your details, but I can run a quick, no-credit-pull numbers check this week and put it in writing. If you'd like that, I'll take your name and number — and if you'd like texts, I'll ask you to check this box so we have your permission. You can reply STOP any time.",objections:[["Just tell me the payment on this one","I'd be guessing — taxes, insurance, down payment and credit all change it. The 15-minute numbers check gets you a real estimate in writing."],["I don't want to be hounded","Fair. You choose how we contact you and how often — and STOP ends texts instantly."],["Are you the listing agent's lender?","I'm an independent lender option. You're welcome to use anyone you like — I'm just here to help with questions."]],next:"Enter sign-ins within 1 hour into Speed-to-Lead with consent flag; Zoho tag 'Open house – {{ADDRESS}}'; Pabbly workflow sends thank-you only to consenting contacts",compliance:"Split open-house costs (food, signage) by actual use per written agreement; nothing of value to the agent for referrals. TCPA: written consent before marketing texts, STOP opt-out. No rate or payment quotes without full disclosures. NMLS #____ on all handouts."}),
SP("P35","Realtor bridge","Offer-strength call to the listing agent",{when:"Buyer's offer is going in, especially multiple-offer or VA/FHA offers",goal:"Make the listing agent confident in the financing",script:"Hi {{FIRST}}, this is Steven Shearrill with Patriot Pacific Financial — I'm the loan officer for {{BUYER}}, whose offer on {{ADDRESS}} you just received. I'll keep this to two minutes.\nWhere the file stands: credit, income and assets have been reviewed by underwriting{{TBD_STATUS}}; the remaining conditions are property-related — appraisal, title, and insurance. We can meet the {{DAYS}}-day close in the offer.\nIf it's a VA loan: the appraisal is a standard appraisal with a short list of health-and-safety items, and if value comes in tight, the Tidewater process gives us a chance to send comps before it's final.\nAnything your seller is nervous about? I'd rather answer it now than after you pick another offer.",objections:[["Cash offers are cleaner","Understood. What I can show is that our conditions are limited and our timeline is firm. I'm happy to talk with your seller directly."],["VA deals fall apart","I'll walk you through exactly how we handle VA appraisals and repairs, and I'll send our VA fact sheet. You'll have my cell the whole way."],["Can you guarantee it closes?","No lender can honestly guarantee that — but I can tell you exactly what's left and I'll call you the moment anything changes."]],next:"Send offer-strength letter + VA fact sheet; log call on Handoff Board; set follow-up for offer response time",compliance:"State only verified file status; do not represent conditional approval as final. No guarantees of closing or value. Buyer must authorize what is shared with the listing side."}),
SP("P36","Realtor bridge","Steven's listing seller wants to buy their next home",{when:"Seller client of Steven (LPT Realty) asks about financing the replacement home",goal:"Sequence the sale and purchase, disclose dual role, and offer choice of lender",script:"{{FIRST}}, congrats on getting the listing live. Before we plan the move-up, the same reminder I give every client: I'm your listing agent through LPT Realty, and I'm also a loan officer with Patriot Pacific Financial. You can use me for the loan, or anyone else — I'll send the written disclosure either way.\nThe real question is timing. We have three paths: buy after your sale closes, buy with a contingency on this sale, or use equity before the sale with something like a HELOC or a bridge option if you qualify. Each one has trade-offs on cost, stress, and how strong your offer looks. Want to set 20 minutes to map them side by side?",objections:[["Can I carry both payments?","That's what we'll check — we'll look at both payments, reserves, and whether a signed sale contract lets us exclude the current payment. I'll show you the math before you commit."],["I don't want a contingent offer","Then we look at pre-sale equity options. They cost something, so we'll compare that cost against the risk of a contingent offer."],["Will you cut your commission if I use you for the loan?","I can't bundle a discount on one side for business on the other. Each side stands on its own and is disclosed."]],next:"Send dual-role disclosure + consent; create move-up scenario in Rate Desk; Handoff Board card 'Sell + Buy'; Zoho tag 'Move-up seller'",compliance:"Dual-role disclosure and information-sharing consent before any loan discussion. No tying of commission discounts to the loan. Bridge/HELOC options subject to qualification; no approval promises. NMLS #____."}),
SP("P37","Escrow deadlines","Loan contingency running short — request extension before it lapses",{when:"Loan contingency date is 3–5 days out and conditions remain open",goal:"Protect the buyer's deposit; get a written extension in place before the deadline",script:"(to buyer's agent) {{FIRST}}, Steven here on {{BUYER}}'s loan. Heads-up before it becomes a problem: loan contingency is {{DATE}}, and we still have {{CONDITIONS}} outstanding. Realistically we'll have final approval by {{ETA}}.\nMy recommendation: request a {{N}}-day extension now, in writing, while there's still time — not on the deadline. I'll write a short status letter you can send the listing agent showing exactly what's done and what's left.\n(to buyer) The contract's contingency is what protects your deposit if financing falls through. Removing it before you have final approval is a decision for you and your agent — and I'd want you to understand the risk first.",objections:[["The seller might say no","Possible — so we ask early and show progress. Most sellers prefer a few days' delay to restarting with a new buyer."],["Can't we just remove it? You said it looks good","'Looks good' isn't final approval. If you remove it and something changes, your deposit could be at risk. That's a call to make with your agent, eyes open."],["Why isn't it done yet?","Here's the exact list and who owes what. I'll update you and your agent every day until it's cleared."]],next:"Send status letter to agent; log contingency date + extension request on Handoff Board; daily status via Pabbly workflow until CTC",compliance:"Never advise removing contingencies or imply final approval; the buyer decides with their agent/attorney. Status letters must reflect actual underwriting status."}),
SP("P38","Escrow deadlines","VA appraisal coming in low — Tidewater notice",{when:"VA appraiser issues a Tidewater notice",goal:"Use the Tidewater window well and set honest expectations",script:"{{FIRST}}, the VA appraiser just sent what's called a Tidewater notice. It means the value may come in below the contract price, and before finalizing, the appraiser is giving us a short window — generally two business days — to send additional sales that support the price.\nHere's the plan: I'm calling your agent now; they'll pull the best closed comps, and we'll submit them through the proper channel today.\nIf value still comes in low, you're protected: the VA amendment in your contract means you can't be forced to pay more than appraised value without forfeiting your deposit. Your options then would be to renegotiate, pay the difference in cash if you choose, request a reconsideration of value, or walk away under that clause.",objections:[["Can't you just call the appraiser?","I'm not allowed to pressure or contact the appraiser to influence value. We submit data through the Tidewater process — that's the right lever."],["Do I lose my deposit if it's low?","The VA amendatory clause protects you from being forced to buy above appraised value. Confirm the details with your agent, but that's what it's there for."],["Will the seller lower the price?","Often there's a negotiation. I'll get you the final number fast so your agent has it."]],next:"Text agent with Tidewater deadline; log on Handoff Board as 'Tidewater – due {{DATE}}'; follow up when the final report is in",compliance:"Appraiser independence: no direct contact or pressure on the appraiser; data goes through the Tidewater/ROV channel only. No promise that value will change."}),
SP("P39","Escrow deadlines","Conventional/FHA low appraisal — Reconsideration of Value (ROV)",{when:"Appraisal received below contract price",goal:"Explain ROV and the borrower's options; keep the deal moving",script:"{{FIRST}}, the appraisal came in at {{VALUE}}, which is {{GAP}} under the price. Four options:\n1) Request a Reconsideration of Value — we submit up to a few better comps or point out factual errors, through our formal process. It's a fair shot, not a guarantee.\n2) Renegotiate the price with the seller.\n3) Cover some or all of the gap in cash, if you have it and want to.\n4) Use your appraisal contingency, if it's still active, to cancel.\nThe clock matters — when is your appraisal contingency? Let's get your agent on the line so we can act before that date.",objections:[["Can we just get a new appraiser?","Ordering a second appraisal isn't something we do to shop for value. The ROV is the proper route if the first report has issues."],["Do I have to pay the difference?","No — that's one option. The others may keep cash in your pocket."],["Is the appraiser wrong?","Sometimes the comps miss something. If your agent finds better sales, the ROV is how we raise them."]],next:"Open ROV in LOS with agent comps; log appraisal contingency date on Handoff Board; notify all parties",compliance:"Appraiser Independence Requirements: borrower-initiated ROV only through the lender's written process; no pressure or value targets. Do not guarantee outcome."}),
SP("P40","Escrow deadlines","Clear-to-close timing vs. COE",{when:"5–7 days before scheduled close of escrow",goal:"Align CTC, CD, signing and funding with COE so nothing slips",script:"{{FIRST}}, quick timeline check for {{ADDRESS}} — COE is {{COE}}.\nWorking backward: to close on {{COE}}, you need to receive the Closing Disclosure at least three business days before signing. That means the CD has to go out by {{CD_DATE}}, and to issue the CD we need clear-to-close — or very close — by {{CTC_DATE}}.\nWhat's still open: {{CONDITIONS}}. If we get those by {{DOC_DATE}}, we're on time. If not, I'll tell you and your agent right away so we can extend before it's an emergency.\nAlso — funding and recording can happen a day or so after you sign, depending on title and escrow. Plan your move and key handoff with your agent around recording, not signing.",objections:[["Why can't we sign the same day the CD comes out?","Federal law requires a waiting period after you receive the CD — it's a consumer protection so you can review the final terms."],["The movers are booked for {{COE}}","Then let's protect that date by clearing these conditions this week. I'll text you the list now."]],next:"Post backward timeline on Handoff Board; Pabbly workflow sends daily condition reminders; confirm signing appointment with escrow",compliance:"TRID: CD must be received at least 3 business days before consummation; no promises on funding/recording times, which depend on third parties."}),
SP("P41","Escrow deadlines","The CD 3-business-day rule — explained to the client",{when:"Client asks why closing can't be moved up, or CD is being issued",goal:"Plain-English TRID explanation that prevents surprises",script:"{{FIRST}}, the Closing Disclosure is the final version of your loan terms and costs. By federal law, you must receive it at least three business days before you sign. For this rule, business days are every day except Sundays and federal holidays — so Saturday counts.\nIf the CD is emailed and you open and acknowledge it today, the clock starts today. If it's only mailed, it's assumed received three business days after mailing, which adds time — so please acknowledge the electronic copy as soon as you get it.\nOnce you have it, compare it to your Loan Estimate. If anything looks different, call me — I'll walk you through every line. A few changes, like an APR increase beyond tolerance, a change in loan product, or adding a prepayment penalty, would restart the three-day wait, which is why we lock everything down early.",objections:[["Can we waive it?","Only for a genuine personal financial emergency, with a written statement from you — it's rare and not for convenience."],["Why did my cash to close change?","Usually prorations, final escrow figures, or credits. I'll go line by line with you."]],next:"Send CD acknowledgement reminder via approved Pabbly text (consented contacts only); calendar CD review call",compliance:"TRID: CD received ≥3 business days before consummation (business day = all days except Sundays and federal holidays). Redisclosure with a new waiting period required for APR increase beyond tolerance, product change, or added prepayment penalty."}),
SP("P42","Escrow deadlines","The CD 3-business-day rule — explained to the agent",{when:"Agent wants to move up closing or add a last-minute change",goal:"Keep the agent informed so a late change doesn't push COE",script:"{{FIRST}}, Steven here. Want to save us both a headache on {{ADDRESS}}. The CD goes out {{CD_DATE}} so the buyer can sign {{SIGN_DATE}}.\nMost late changes — a repair credit, a small price adjustment — mean a revised CD but don't restart the three-day clock. Three things do restart it: the APR going up beyond tolerance, a change in loan product, or adding a prepayment penalty. A price change that changes the loan amount can also change the APR.\nSo if anything is still being negotiated, let me know today, not at signing. I'd rather issue the CD with the final numbers once.",objections:[["We just need to add a seller credit","Tell me the amount now — credits have limits by loan type, and I'll confirm it fits before escrow amends."],["Can we close a day early?","Only if the CD has been received for three business days by then. Let me check the dates and I'll tell you in ten minutes."]],next:"Note any pending amendments on Handoff Board; verify concession limits in Rate Desk before amendment",compliance:"TRID timing and redisclosure triggers as stated; seller credit limits depend on program (e.g., VA concessions cap of 4%, excluding normal closing costs)."}),
SP("P43","Escrow deadlines","Rate lock expiring before COE",{when:"Lock expires before the projected funding date",goal:"Explain options and costs before the lock lapses",script:"{{FIRST}}, your rate lock expires {{LOCK_DATE}}, and with {{REASON}}, closing is now projected for {{COE}}. I want you to have options before it expires, not after.\nOption 1: extend the lock — there's usually a cost per day or per block of days, which I'll confirm in writing today.\nOption 2: let it expire and relock at the market — that could be better or worse; nobody can predict it, and typically worse-case pricing applies to relocks.\nOption 3: push hard to close inside the current lock — if the remaining items can realistically be done.\nIf the delay was on our side, I'll tell you plainly and talk to management about who covers the extension. Which way are you leaning?",objections:[["Why should I pay for a delay?","If it's a lender delay, I'll escalate that. If it's from the seller or the property, we'll look at whether the contract lets your agent ask for the cost to be covered."],["Can't you just give me the same rate?","Pricing is locked for a set period. I'll show you the extension cost in writing so you can decide."]],next:"Price extension in Rate Desk; send written options; log decision and new lock date on Handoff Board",compliance:"Disclose extension fees accurately in writing; changes to rate/points require revised disclosures per TRID. No predictions about market direction."}),
SP("P44","ISA desk","Voicemail — new inbound lead",{when:"First call attempt goes to voicemail",goal:"Leave a short, compliant voicemail that earns a callback",script:"Hi {{FIRST}}, this is {{AGENT}} with Steven Shearrill's team at Patriot Pacific Financial. You requested info about {{TOPIC}}, and I have a couple of quick answers for you.\nYou can reach me at {{CALLBACK}}. I'll also send a short text — with your permission on file — so you have my number. Talk soon.",objections:[["(Callback) Who is this again?","{{AGENT}} with Steven Shearrill's team at Patriot Pacific — you asked about {{TOPIC}} on {{DATE}}. Is now still a good time for two quick questions?"],["(Callback) How did you get my number?","You submitted a request on {{SOURCE}} on {{DATE}}. If you'd rather not hear from us, I'll mark you do-not-contact right now."]],next:"Log attempt in Speed-to-Lead; send follow-up text only if SMS consent flag is true; Zoho tag 'VM1'",compliance:"Identify company and caller; no rates. TCPA: texts only with prior consent; respect quiet hours (stricter in some states, e.g., Florida). Company/individual NMLS #____ in written follow-ups."}),
SP("P45","ISA desk","Follow-up text after voicemail",{when:"Immediately after voicemail, if the lead gave SMS consent",goal:"Make it easy to reply or book",script:"Hi {{FIRST}}, {{AGENT}} with Steven Shearrill's team at Patriot Pacific Financial (NMLS #____). Just left you a quick voicemail about {{TOPIC}}. Easiest next step is a free 15-min numbers check with Steven — want {{TIME1}} or {{TIME2}}? Reply STOP to opt out.",objections:[["(Reply) Who is this?","{{AGENT}} with Steven Shearrill's mortgage team — you asked about {{TOPIC}} on {{DATE}}. Happy to help whenever you're ready."],["(Reply) What's the rate?","It depends on your scenario, so I'd be guessing. Steven can show you today's pricing for your situation on a quick call and confirm it in writing."],["(Reply) STOP","(System auto-confirms opt-out; no further texts. Do not reply manually.)"]],next:"Pabbly workflow logs reply to Zoho; STOP sets do-not-text flag; booked replies go to Speed-to-Lead as 'Booked'",compliance:"TCPA: prior express (written, for marketing) consent required; include opt-out; honor STOP immediately across all systems. No rates or terms in texts."}),
SP("P46","ISA desk","No-show reschedule",{when:"Lead missed a booked consult",goal:"Reschedule without guilt; find the real blocker",script:"Hi {{FIRST}}, it's {{AGENT}} from Steven Shearrill's team. We had you down for {{TIME}} today — no worries at all, life happens.\nSteven still has your notes, so the call will be quick. Would {{TIME1}} or {{TIME2}} work better? … And just so I set it up right — is the timing still good for you, or did something change with your plans?",objections:[["I forgot","Totally normal. I'll send a calendar invite and a reminder text the morning of — if that's okay with you."],["I'm not sure I'm ready","That's fine. The call is just to see where you stand — no credit pull, no pressure. Want me to check back in a month instead?"],["I talked to another lender","Good to compare. If you'd like a second set of eyes on their Loan Estimate, Steven's happy to look — no obligation."]],next:"Rebook in TidyCal; Zoho tag 'No-show 1'; if no answer, one text (consented) and one more call in 48 hours, then move to nurture",compliance:"Two-attempt cadence then nurture; TCPA consent for texts; honor any opt-out."}),
SP("P47","ISA desk","4:10 PM handoff to Steven",{when:"Daily 4:10 PM — hot leads from the day go to Steven",goal:"Warm, complete handoff so Steven never asks the client to repeat themselves",script:"(to Steven, internal) Steven — 4:10 handoff, three hot ones.\n1) {{FIRST}} {{LAST}}: buying in {{AREA}}, veteran with COE pending, wants to be in a home by {{MONTH}}. Self-reports credit as good, savings for closing costs. Agent: none yet. Best time: after 5:30. Consent to text: yes.\n2) …\n(to client, warm transfer) {{FIRST}}, I've got Steven on the line. Steven, {{FIRST}} is looking at {{TOPIC}} and wants to understand {{QUESTION}}. I've shared my notes, so you two can pick up right there.",objections:[["(Client) Can't you just answer it?","I can help with the basics, but Steven is the licensed loan officer — he can actually give you numbers for your situation."],["(Client) I only have a minute","Then let's book 15 minutes with Steven at a time that works — {{TIME1}} or {{TIME2}}?"]],next:"Move each lead to 'Steven' column on Handoff Board with notes; Zoho tag 'Handoff 4:10'",compliance:"ISA does not quote rates, terms, or qualification decisions (unlicensed activity); Steven (NMLS #____) handles all loan-specific discussion."}),
SP("P48","ISA desk","After-hours lead",{when:"Lead arrives after 7 PM or on weekends",goal:"Acknowledge quickly without calling at bad hours",script:"(Auto/approved text if consent on file) Hi {{FIRST}}, thanks for reaching out to Steven Shearrill's team at Patriot Pacific Financial (NMLS #____). We got your request about {{TOPIC}}. Someone will call you tomorrow after 9 AM — or grab a time here: {{BOOKING_LINK}}. Reply STOP to opt out.\n(Next-morning call) Hi {{FIRST}}, it's {{AGENT}} following up on the request you sent last night about {{TOPIC}}. Is now a good time?",objections:[["(Lead calls back late) Can someone talk tonight?","If Steven is available, I'll see if he can call you — otherwise, first thing tomorrow, and I'll put you at the top of the list."],["I needed an answer last night","Understood, and I'm sorry for the wait. Let's get you answers right now — what's the most pressing question?"]],next:"Speed-to-Lead queue 'After hours' for first-call next morning; Pabbly sends acknowledgement only to consenting contacts",compliance:"TCPA/state quiet hours: no calls or marketing texts outside permitted hours (TCPA 8 AM–9 PM recipient local time; some states stricter, e.g., Florida). Automated texts require prior express written consent."}),
SP("P49","ISA desk","Spanish-speaking lead — offer a Spanish-speaking colleague",{when:"Lead prefers Spanish",goal:"Respectful handoff to a Spanish-speaking team member; keep the lead warm",script:"(If you don't speak Spanish) Thank you, {{FIRST}}. I want to make sure you get the best help — would you prefer to speak with a colleague who speaks Spanish? (pause) Great. I'll set that up right now. What's the best time today or tomorrow for them to call you?\n(If they prefer to continue in English) Of course — and if anything gets confusing, just say so and I'll bring in a Spanish-speaking colleague any time.\n(Translated disclosures) I'll also ask whether the documents can be provided in Spanish where available — the binding documents may still be in English, so your colleague will review them with you.",objections:[["Do you have someone now?","Let me check availability. If not right now, I'll book the earliest time and confirm by your preferred method."],["My son will translate","That's fine if you'd like — and you're always welcome to have a team member who speaks Spanish join as well."]],next:"Assign to Spanish-speaking team member in Zoho (tag 'Language: Spanish'); move card on Handoff Board; log preferred language",compliance:"Fair lending/ECOA: equal service regardless of national origin; don't steer products by language. Track language preference per agency guidance; clarify which documents are available in Spanish and that the English version controls where applicable."}),
SP("P50","ISA desk","Lead says 'stop calling me'",{when:"Lead asks not to be contacted",goal:"Honor the request instantly and politely",script:"Absolutely, {{FIRST}} — I'm sorry for the bother. I'm marking you as do-not-contact right now for calls and texts. If you ever want help in the future, you're welcome to reach out to us. Have a good day.",objections:[["(After opt-out, lead later calls in)","Thanks for calling back! I see you asked us not to contact you before — I'm happy to help today. Would you like to update your contact preferences?"],["Take me off every list","Done for our team. I'll make sure the do-not-contact flag is set across our systems today."]],next:"Set DNC flag in Zoho; Pabbly workflow removes from all sequences; log date/time of request",compliance:"TCPA/Do-Not-Call: honor revocation of consent promptly by any reasonable means; maintain internal DNC list; no further marketing contact."}),
SP("P51","Equity","HELOC vs. home equity loan vs. cash-out refi",{when:"Homeowner asks 'how do I get cash out of my house?'",goal:"Clear comparison so the client chooses based on goals",script:"{{FIRST}}, there are three main ways to tap equity, and the right one depends on how you'll use the money and how you feel about your current first mortgage.\n1) HELOC — a line of credit, usually variable rate. You draw what you need, when you need it, and typically pay interest only on what you've used during the draw period. Good for projects or costs that come in stages.\n2) Home equity loan — a lump sum, usually a fixed rate and fixed payment. Good when you know the exact amount.\n3) Cash-out refinance — replaces your first mortgage with a bigger one. Makes sense mainly when the new first-mortgage terms would also work for you.\nI'll lay out all three with today's pricing, which I'll confirm in writing, plus total costs over the time you expect to keep the loan.",objections:[["Which is cheapest?","It depends on amount, timeline, and your current rate. That's why I show all three side by side, with the total cost — not just the rate."],["Is a variable rate risky?","It can go up as well as down. We'll look at what the payment could be if the rate rises, so you can decide with eyes open."],["How much can I get?","It depends on value, your current balance, and program limits. I'll estimate it and confirm with an appraisal or valuation."]],next:"Run Equity calc (HELOC vs HELOAN vs cash-out) and send comparison; Zoho tag 'Equity – compare'",compliance:"No rate quotes without full disclosures; HELOC is open-end credit (Reg Z HELOC disclosures apply). Explain variable-rate risk and that the home secures the debt."}),
SP("P52","Equity","Debt consolidation — show the math, no promises",{when:"Client wants to roll credit cards/auto loans into the house",goal:"Honest side-by-side so the client can decide",script:"{{FIRST}}, let's look at this honestly. Consolidating can lower your monthly payment, but that's not the same as saving money. Here's what I'll show you:\nColumn 1 — your current debts: balance, payment, and how long until each is paid off.\nColumn 2 — the consolidation option: new payment, the costs to do the loan, and the total you'd pay if you only made the minimum.\nColumn 3 — the same option if you kept paying what you pay now, which shortens the term.\nAlso important: these debts would become secured by your home, and if the cards run back up, you'd be worse off. If the numbers work and you're comfortable, great. If not, I'll tell you.",objections:[["Will this save me money?","Maybe on a monthly basis — total cost depends on the term and what you do after. That's why I show you all three columns."],["Will it raise my credit score?","I can't promise that. Scores depend on many factors; your lender-pulled credit report will tell us where you stand today."],["I just want the lowest payment","Then we'll look at that option too — and make sure you see what stretching it out costs over time."]],next:"Build Debt Consolidation comparison in Equity calc; send with disclosures; Zoho tag 'Consolidation'",compliance:"No promises of savings or score improvement; disclose closing costs and total cost over life; note unsecured debt becomes secured by the home."}),
SP("P53","Equity","'Don't touch my 3% first mortgage'",{when:"Client has a low-rate first mortgage and wants cash",goal:"Preserve the first lien; offer a second-lien option",script:"Totally agree — we're not touching your first mortgage. If you need {{AMOUNT}} for {{PURPOSE}}, we can look at a second lien sitting behind it: a HELOC if you'll draw over time, or a fixed-rate home equity loan if you want one lump sum and a set payment.\nYour first mortgage stays exactly as it is. We compare the cost of the second lien to the alternatives — like waiting, saving, or a smaller amount — so you can decide.\nI'll show you a blended view too: what your total housing payment would be with both loans, based on today's pricing, which I'll confirm in writing.",objections:[["Why is the rate on the second higher?","Second liens carry more risk to the lender because they're paid after the first. That's why we keep the amount targeted to what you need."],["What if rates go up on the HELOC?","We'll show you a higher-rate scenario so you know the payment range, and a fixed-rate equity loan is an option if you prefer certainty."]],next:"Run second-lien scenario in Equity calc; send blended payment summary; Zoho tag 'Keep first lien'",compliance:"Reg Z disclosures for open-end (HELOC) and closed-end seconds; no rate quotes without disclosures; explain variable-rate risk."}),
SP("P54","Equity","HELOC for the down payment on a second home",{when:"Homeowner wants to use equity to buy a vacation/second home",goal:"Map both loans and the qualifying impact",script:"{{FIRST}}, this is a common strategy, and it can work well — but we plan both loans together.\nStep 1: we set up a HELOC on your current home before you write offers, since lenders generally want the line in place and documented.\nStep 2: for the second-home loan, the HELOC payment counts in your debt-to-income, and the funds are borrowed, so we document them correctly.\nStep 3: second-home rules matter — it needs to be a reasonable distance from your primary residence, for your personal use, and not a rental. If it'll be rented, we'd look at investor financing instead.\nI'll put both payments together so you see your total monthly obligation before you commit.",objections:[["Can I just put it on the HELOC and not tell the lender?","No — all borrowed funds and debts have to be disclosed. Done right, it's a perfectly acceptable strategy."],["What if I rent it out sometimes?","Then it may not fit second-home rules. Let's talk through how you'll use it so we pick the right program."],["How much do I need down?","It depends on the program and your profile; I'll show you options based on today's guidelines in writing."]],next:"Open two linked files (HELOC + purchase) on Handoff Board; run DTI with both payments; Zoho tag 'Second home – HELOC'",compliance:"Borrowed down payment must be disclosed and documented; second-home occupancy rules must be met — no misrepresentation of occupancy. No rate quotes without disclosures."}),
SP("P55","Equity","HELOC draw period ending — payment change call",{when:"Client's HELOC moves from draw to repayment within 6–12 months",goal:"Prevent payment shock; review options early",script:"{{FIRST}}, this is {{AGENT}} with Steven Shearrill's team. I'm calling ahead because your HELOC's draw period ends around {{DATE}}. After that, the payment usually changes from interest-only to principal plus interest, which can be a noticeable jump.\nSteven would like to show you three things: what the new payment is expected to be, whether paying down part of the balance now helps, and whether refinancing the line into a fixed equity loan makes sense. Nothing to decide today — just a 15-minute review. {{TIME1}} or {{TIME2}}?",objections:[["I didn't know it changes","That's exactly why we're calling early. Your HELOC agreement spells it out; we'll walk through it together."],["I can't afford a higher payment","Let's look at options now while you have time — that's much better than finding out with the first new bill."]],next:"Book review; pull HELOC terms; Annual Mortgage Review card flagged 'HELOC repayment'",compliance:"Reference the client's actual HELOC agreement; no promises of approval or lower payment on any refinance option."}),
SP("P56","Equity","Equity for home improvements or an ADU",{when:"Client wants to remodel or build an ADU",goal:"Match financing to the project timeline",script:"{{FIRST}}, for projects the big question is timing. Contractors get paid in stages, so a HELOC often fits — you draw as each phase is done.\nFor an ADU, we should also talk about whether a renovation or construction-style loan fits better, since those can consider the finished value. Each comes with its own requirements, like contractor bids and inspections.\nBring me your bids and timeline, and I'll lay out two or three options based on today's pricing, which I'll confirm in writing.",objections:[["Can the ADU rent help me qualify?","Some programs allow projected rent in certain cases with documentation. I'll confirm what applies before you count on it."],["Do I need permits?","Yes — lenders generally require permitted work, and it protects your home's value."]],next:"Collect bids; run Equity calc and renovation scenario; Zoho tag 'ADU/Remodel'",compliance:"No rate quotes without disclosures; don't promise use of projected rental income or after-improved value until confirmed by guidelines."}),
SP("P57","Reverse","HECM basics with adult children present",{when:"First reverse conversation with the homeowner and family",goal:"Transparent explanation; everyone hears the same facts",script:"Thank you all for being here. Let me start with the basics of a Home Equity Conversion Mortgage, or HECM:\n• The borrower must be at least 62 and live in the home as a primary residence.\n• Mom keeps title — the home stays in her name.\n• She doesn't make a required monthly mortgage payment, but she must keep paying property taxes, homeowners insurance, HOA dues if any, and maintain the home. That's non-negotiable.\n• The loan is repaid when the last borrower permanently leaves the home. Heirs can keep the home by paying off the loan — or the lesser of the balance or 95% of appraised value — or sell and keep any remaining equity.\n• It's non-recourse: no one owes more than the home is worth.\n• Before we go further, she'll meet with an independent HUD-approved counselor. That's required, and you're welcome to attend.",objections:[["We want to protect our inheritance","Understandable. The balance grows over time, so there will likely be less equity left. We'll show you projections so the whole family decides with clear numbers."],["Is this a scam?","It's a federally insured program with required independent counseling. Take your time, ask the counselor anything, and involve your own advisors."],["Can we be on the loan?","Only borrowers who meet the age and occupancy rules can be borrowers; we'll talk about eligible spouses separately."]],next:"Send HUD counseling agency list; log family contacts with borrower's permission; Zoho tag 'Reverse – family'",compliance:"HECM requires HUD-approved counseling before application; borrower 62+; ongoing obligations for taxes, insurance, maintenance. No pressure; borrower controls who receives information."}),
SP("P58","Reverse","HECM for Purchase",{when:"Senior wants to downsize/rightsize without a monthly mortgage payment",goal:"Explain how H4P works and what's needed",script:"{{FIRST}}, a HECM for Purchase lets you buy your next home using a reverse mortgage plus a down payment from your own funds — often the proceeds from selling your current home.\nYou'd have no required monthly mortgage payment, but you still pay taxes, insurance, HOA, and keep up the home. You'll need to move in as your primary residence within the program's timeframe.\nThe down payment depends on your age, the home price, and current pricing, and I'll calculate it in writing. And like every HECM, it starts with a session with an independent HUD-approved counselor.\nWould you like your real estate agent and family on the next call?",objections:[["How much do I need to put down?","It varies by age, price and pricing. I'll run your numbers and give you a written estimate."],["Can I buy a fixer?","The home has to meet FHA property standards, so major repairs can be an issue. Let's review the home before you write the offer."],["Will my agent know how this works?","Some do. I'll walk your agent through timelines and property requirements so there are no surprises."]],next:"Run HECM purchase estimate; send counseling agency list; Handoff Board card 'H4P'",compliance:"HUD counseling required; borrower 62+; principal residence occupancy; ongoing taxes/insurance/maintenance; down payment from allowable sources. No guarantees on proceeds."}),
SP("P59","Reverse","Myth-busting: 'the bank takes the house'",{when:"Senior or family raises common reverse mortgage myths",goal:"Replace myths with accurate facts",script:"Let's go through the big ones:\nMyth 1: 'The bank owns my home.' False — you keep title.\nMyth 2: 'My kids will owe money.' False — HECMs are non-recourse. If the balance exceeds the home's value, FHA insurance covers the gap; heirs don't pay the difference.\nMyth 3: 'I can never be foreclosed on.' Not quite — if property taxes, insurance, or upkeep aren't maintained, or the home is no longer the primary residence, the loan can become due. That's why we plan for those costs up front.\nMyth 4: 'It's only for people who are broke.' Many people use it as a planning tool. Whether it fits you is something to discuss with the counselor and your own advisors.",objections:[["My neighbor lost her house","I'm sorry to hear that. Often it's tied to unpaid taxes or insurance — which is why we look at a set-aside for those costs if needed."],["Why do the ads sound too good?","Ads simplify. Counseling exists so you hear the full picture, including costs."]],next:"Send plain-language HECM fact sheet; book counseling; Zoho tag 'Reverse – myths'",compliance:"Accurately state default triggers (taxes, insurance, maintenance, occupancy); no 'can't lose your home' claims; counseling required."}),
SP("P60","Reverse","The counseling requirement",{when:"Borrower is ready to move forward with a HECM",goal:"Explain counseling and get it scheduled",script:"{{FIRST}}, the next step is required by HUD: a session with an independent, HUD-approved HECM counselor. They don't work for us, and that's the point — they make sure you understand the costs, alternatives, and your obligations.\nI'll send you a list of approved agencies; you choose one. It's usually by phone or video. You'll get a certificate afterward, and we can't take your application until we have it.\nIt helps to have your property tax bill, insurance policy, and a rough monthly budget handy. Family can join if you'd like.",objections:[["Do I have to pay for it?","Some agencies charge a fee and some may waive it based on your situation — ask them directly."],["Can't you just explain it?","I'm happy to answer any questions, but the law requires an independent counselor too — it's a protection for you."]],next:"Send HUD-approved counselor list; set follow-up for certificate; Handoff Board 'Awaiting counseling cert'",compliance:"HECM counseling by a HUD-approved agency required before application; lender may not steer to a specific counselor."}),
SP("P61","Reverse","Non-borrowing spouse conversation",{when:"One spouse is under 62 or not on title",goal:"Explain protections and limits clearly",script:"{{FIRST}}, because your spouse is under 62, they wouldn't be a borrower on the HECM. Current HUD rules include protections that may allow an eligible non-borrowing spouse to stay in the home after the borrower passes, as long as conditions are met — like being married at closing, living there as a primary residence, and continuing to pay taxes and insurance.\nBut a non-borrowing spouse can't draw additional funds after the borrower is gone, and the amount available is calculated based on the younger spouse's age. That means less money available up front.\nThe counselor will walk through this with both of you, and I'll give you a written estimate.",objections:[["So I could lose the house?","The protections are designed to prevent that if conditions are met. We'll go through each one so you both know them."],["Why is the amount lower?","Because the loan is expected to run longer with a younger spouse, so less is available up front."]],next:"Document marital status and ages; include both spouses in counseling; Zoho tag 'Reverse – NBS'",compliance:"Accurately describe HUD non-borrowing spouse protections and limits; both spouses should attend counseling; no guarantees."}),
SP("P62","Reverse","Taxes, insurance and the set-aside (LESA)",{when:"Financial assessment shows tight cash flow or past tax/insurance issues",goal:"Explain why a set-aside may be required and how it protects the borrower",script:"{{FIRST}}, as part of every HECM we do a financial assessment — a look at income, credit and history of paying property charges. It's not about a minimum score; it's about making sure you can keep up with taxes and insurance, since those are the main reasons a reverse mortgage can go into default.\nBased on what we see, we may need to set aside part of your loan proceeds — called a Life Expectancy Set-Aside — to pay those bills for you. It means less cash up front, but it takes that worry off your plate.",objections:[["I want all the money now","I understand. The set-aside depends on the financial assessment rules; I'll show you exactly why and the numbers either way."],["I've always paid my taxes","Great — then we document that, and it may not be needed. Bring your last couple of tax bills and insurance policy."]],next:"Gather tax/insurance history; run financial assessment; update borrower with written estimate",compliance:"HECM financial assessment and LESA requirements per HUD; disclose impact on available proceeds."}),
SP("P63","Refi","VA IRRRL — net tangible benefit & 36-month recoupment",{when:"VA borrower asks about an IRRRL",goal:"Explain requirements honestly; only proceed if it helps",script:"{{FIRST}}, the IRRRL is VA's streamline refinance. Before we do one, two tests have to be met:\n1) Net tangible benefit — for example, a fixed-to-fixed refinance generally needs the rate to drop by at least half a percentage point, and the loan has to actually leave you better off.\n2) Recoupment — the closing costs have to be recouped through the monthly savings within 36 months.\nThere's also seasoning: your current loan needs at least six payments made and 210 days since the first payment due date.\nThe VA funding fee on an IRRRL is 0.50% unless you're exempt — for example, if you receive VA disability compensation.\nIf your numbers pass, I'll send them to you in writing with today's pricing, which I'll confirm. If they don't pass, I'll tell you, and we'll watch for a better time.",objections:[["Do I need an appraisal?","Generally VA doesn't require one for an IRRRL, though a lender may in some cases."],["I'm renting out the house now","For an IRRRL you only need to certify you previously lived there — so that can still work."],["Will I restart 30 years?","We can look at matching your remaining term or going shorter."]],next:"Run IRRRL tester (NTB + recoupment); send results; Zoho tag 'IRRRL candidate'",compliance:"IRRRL: net tangible benefit and fee recoupment within 36 months required; seasoning 210 days/6 payments; 0.50% funding fee unless exempt. No promised savings; written disclosures."}),
SP("P64","Refi","FHA Streamline refinance",{when:"FHA borrower asks if they can lower their payment",goal:"Explain the streamline and its tests",script:"{{FIRST}}, FHA has a streamline refinance that can reduce documentation — often no appraisal and limited income docs with a non-credit-qualifying version.\nRequirements: your current loan must be FHA, it needs to be seasoned — at least 210 days since closing and six payments made — and you need to be current on payments. FHA also requires a net tangible benefit, which usually means your combined rate and mortgage insurance must come down by a meaningful amount.\nWe'll check your MIP too — depending on when your loan closed, the streamline may change your MIP or its refund credit.\nI'll run the numbers with today's pricing and confirm everything in writing.",objections:[["Can I take cash out?","Not with a streamline — that's a different FHA program."],["Will my mortgage insurance go away?","Not with an FHA streamline — FHA keeps MIP. If you have enough equity, we can compare a conventional refinance that could remove it."],["Do I need a credit check?","Some lenders allow non-credit-qualifying versions, but we'll still review payment history."]],next:"Run FHA streamline NTB test; pull case number history; send comparison",compliance:"FHA streamline: seasoning and net tangible benefit required; no rate quotes without full disclosures; no savings guarantees."}),
SP("P65","Refi","No-cost refinance — the trade-off",{when:"Client asks for a 'no-closing-cost' refinance",goal:"Explain lender credits vs. rate",script:"{{FIRST}}, a no-cost refi isn't free — it just changes how you pay. We'd choose a slightly higher rate, and the lender credit covers your closing costs.\nIt can make sense if you might move or refinance again in a few years, since you're not paying costs up front. If you plan to stay long-term, paying some costs for a lower rate may cost less over time.\nI'll show you two or three options side by side — the payment, the costs, and the break-even point — based on today's pricing, which I'll confirm in writing.",objections:[["Is there a catch?","The catch is a higher rate than you'd get by paying costs. That's the trade, and I'll show it in plain numbers."],["Do prepaid items count?","Escrows and prepaid interest are separate. I'll show what the credit covers."]],next:"Run no-cost vs. cost options in Rate Desk; send comparison with LE",compliance:"Disclose lender credits and rate trade-off on LE; no rate quotes without disclosures; no 'free' claims."}),
SP("P66","Refi","'Rates dropped — why haven't you called?'",{when:"Past client calls frustrated after reading headlines",goal:"Own it, check eligibility honestly, rebuild trust",script:"{{FIRST}}, thank you for calling — and you're right to ask. Headlines often talk about averages, and whether a refinance helps you depends on your current rate, balance, remaining term, and costs.\nLet me run your loan right now. I'll check whether the savings are meaningful after costs and how long it takes to break even. If it makes sense, I'll send it in writing today with current pricing, which I'll confirm. If it doesn't, I'll show you why — and set a rate watch so we call you the moment it does.",objections:[["My neighbor just refinanced","Their loan may differ — rate, balance, term, or program. I'll show you your exact numbers."],["I should have heard from you","Fair. I'm adding you to our Annual Mortgage Review and rate watch so you hear from us proactively."]],next:"Run refi analysis in Rate Desk; enroll in Annual Mortgage Review and rate watch; Zoho tag 'Rate watch'",compliance:"No rate predictions; no savings promises; disclose costs and break-even in writing."}),
SP("P67","Refi","VA cash-out refinance",{when:"Veteran wants to take cash out or refinance a non-VA loan into VA",goal:"Explain rules, costs, and the NTB requirement",script:"{{FIRST}}, VA cash-out lets you refinance any loan — VA or not — into a VA loan and take cash out, depending on value and lender limits.\nA few rules: the home must be your primary residence; your current loan needs six payments and 210 days of seasoning; and VA requires a net tangible benefit and loan comparison disclosures.\nFunding fee: 2.15% for first use or 3.30% for subsequent use — unless you're exempt, for example, if you receive VA disability compensation.\nVA also looks at residual income — the money left each month after major expenses — so we'll make sure the new payment fits comfortably.",objections:[["Why is the funding fee so high?","It helps fund the VA program. If you're exempt, you won't pay it. We'll check your COE."],["Can I go to 100%?","VA allows up to 100% of value in some cases, but lender limits vary. I'll show you what's available today."],["Should I just do a HELOC?","Maybe — I'll compare both, especially if your current rate is lower than today's options."]],next:"Pull COE; run cash-out vs. HELOC in Equity calc; send VA comparison disclosures",compliance:"VA cash-out: NTB and comparison disclosures required; funding fee 2.15%/3.30% unless exempt; residual income applies; no rate or approval guarantees."}),
SP("P68","Refi","Conventional refinance to remove PMI",{when:"Value or balance changes may allow PMI removal or a better loan",goal:"Compare PMI cancellation vs. refinance",script:"{{FIRST}}, there may be two ways to drop PMI. First, your current servicer may cancel it once you reach certain equity levels and meet their requirements — sometimes with a new appraisal. That's often cheaper than refinancing.\nSecond, if refinancing also improves your rate or term, it might make sense to do both at once.\nLet's call your servicer first to ask about their PMI removal process, then I'll compare a refinance only if it helps.",objections:[["Can't you just remove it?","Only your servicer can cancel PMI on your current loan; a refinance replaces the loan entirely."],["Do I need an appraisal?","Maybe — depends on your servicer and loan. We'll check."]],next:"Send PMI removal checklist; run refi comparison only if beneficial; Annual Mortgage Review flag 'PMI check'",compliance:"Follow Homeowners Protection Act requirements; don't promise PMI removal; refinance only if it provides a benefit."}),
SP("P69","Refi","IRRRL on a rental property (prior occupancy)",{when:"VA borrower moved and now rents out the home",goal:"Clarify occupancy rules",script:"{{FIRST}}, good news: for a VA IRRRL, you only need to certify that you previously lived in the home. So even if it's a rental now, it may qualify.\nThe same tests apply: net tangible benefit, recoupment within 36 months, seasoning, and a 0.50% funding fee unless you're exempt.\nWe'll also check that the loan you're refinancing is your VA loan — an IRRRL can only refinance an existing VA loan.\nI'll run your numbers and send them in writing.",objections:[["Do I need to move back in?","No — prior occupancy is enough for an IRRRL."],["Can I do cash-out on it?","VA cash-out requires the home to be your primary residence, so that wouldn't work for a rental."]],next:"Run IRRRL tester; verify prior occupancy; Zoho tag 'IRRRL – rental'",compliance:"IRRRL prior-occupancy certification; NTB and recoupment; 0.50% funding fee unless exempt."}),
SP("P70","Niches","Piggyback / second-lien purchase (80-10-10)",{when:"Buyer wants to avoid PMI or stay under a loan limit",goal:"Compare piggyback vs. single loan with PMI",script:"{{FIRST}}, a piggyback is two loans at closing — for example, a first mortgage at 80% of the price, a second at 10%, and 10% down. It can avoid PMI or keep the first loan under a conforming limit.\nTrade-offs: the second lien often has a higher rate, sometimes variable, and it's a second payment. PMI on a single loan can be cancelled later, while the second loan has to be paid down or refinanced.\nI'll compare both options — total payment, costs, and how each looks after a few years — with today's pricing, which I'll confirm in writing.",objections:[["PMI is wasted money","It's a cost, but it can be removed later. The second lien also costs money. Let's compare both."],["Can the second be fixed?","Sometimes — it depends on the lender and program. I'll show you options."]],next:"Run piggyback vs. PMI comparison in Rate Desk; send summary",compliance:"Disclose both loans' terms; no rate quotes without disclosures; explain variable-rate risk if applicable."}),
SP("P71","Niches","Seller concessions → permanent buydown or 2-1 buydown",{when:"Buyer has seller credit to use",goal:"Explain how to use credits strategically",script:"{{FIRST}}, if the seller is offering a credit, there are a few ways to use it:\n1) Closing costs — reduces your cash needed.\n2) Permanent buydown — buys the rate down for the life of the loan.\n3) Temporary buydown, like a 2-1 — lowers your payment in years one and two, then goes to the note rate. You qualify at the note rate, and unused funds are typically applied according to program rules.\nWhich is best depends on how long you'll keep the loan and how much cash you have. Also, each program limits seller concessions — for example, VA caps concessions at 4% of value, not counting normal closing costs.\nI'll lay out all options side by side with today's pricing, which I'll confirm in writing.",objections:[["Isn't the 2-1 always better?","Not always. It helps early, but a permanent buydown can save more if you keep the loan long-term."],["What if rates drop?","We can't predict that. If you refinance, unused buydown funds are handled per program rules — we'll review that."]],next:"Run buydown calc in Rate Desk; confirm seller concession limits; send options",compliance:"Concession limits by program (VA 4% excluding normal closing costs; conventional limits by LTV/occupancy; FHA limits); temporary buydowns qualify at note rate; no rate predictions."}),
SP("P72","Niches","Investor / DSCR loan",{when:"Investor wants to qualify on rental income instead of personal income",goal:"Explain DSCR and set expectations",script:"{{FIRST}}, a DSCR loan qualifies the property based on its rent compared to the payment — principal, interest, taxes, insurance, and HOA. Your personal income generally isn't used.\nIt's business-purpose financing, so it's for investment properties only, and pricing often depends on the DSCR ratio, credit, and down payment.\nWe'll need a lease or a rent estimate from the appraisal, plus reserves. I'll show you options with today's pricing, which I'll confirm in writing.",objections:[["What ratio do I need?","It varies by program. Some allow ratios below 1.0 with adjustments. I'll show you options."],["Can I live in it?","No — DSCR loans are for investment properties only."]],next:"Run DSCR calc; Zoho tag 'DSCR'; request rent roll or lease",compliance:"Business-purpose certification; no owner occupancy; non-QM disclosures where applicable; no rate quotes without disclosures."}),
SP("P73","Niches","Non-QM bank statement loan",{when:"Self-employed borrower with large write-offs",goal:"Explain bank statement qualifying",script:"{{FIRST}}, if your tax returns don't show your real cash flow because of write-offs, a bank statement loan uses 12 or 24 months of business or personal statements to calculate income, often with an expense factor or a CPA letter.\nIt's a non-QM program, so pricing and down payment differ from conventional. I'll show you options and the trade-offs with today's pricing, which I'll confirm in writing.",objections:[["Is it more expensive?","Usually yes compared to conventional. We'll compare and look at refinancing later if your taxes show more income."],["Do I need a CPA?","Some programs require a CPA letter or a P&L; we'll confirm."]],next:"Collect statements; calculate qualifying income; Zoho tag 'Bank statement'",compliance:"Non-QM ability-to-repay documentation; no misstatement of income; disclose program terms."}),
SP("P74","Niches","Adding a new state — licensing announcement",{when:"Steven expands or reminds partners of licensing in {{STATE}}",goal:"Announce licensing accurately and invite referrals",script:"Hi {{FIRST}}, quick update: Steven Shearrill with Patriot Pacific Financial is licensed to originate mortgage loans in {{STATE}} (NMLS #____). That means we can help your clients there with purchases, refinances, VA loans, and more.\nIf you have clients moving to or from {{STATE}}, we'd be glad to help.",objections:[["Do you know the local market?","We partner with local agents and title/escrow pros, and I'll learn your market quickly."],["Are you licensed for real estate there too?","Steven's real estate license is in California only; this is for mortgage lending."]],next:"Update licensing footer; Zoho tag 'State – {{STATE}}'; Pabbly workflow sends announcement to opted-in partners",compliance:"Verify license status in NMLS before announcing; include NMLS #____ and state license info where required; no rates in announcements."}),
SP("P75","Niches","Seller credit math on a VA purchase (agent call)",{when:"Agent wants to write a large seller credit on a VA offer",goal:"Confirm what counts toward VA's 4% cap",script:"{{FIRST}}, on VA, seller concessions are capped at 4% of the property's reasonable value, but normal closing costs — things like the loan's standard fees and title charges — don't count toward that 4%.\nItems that do count include paying the buyer's funding fee, prepaid taxes and insurance, paying off buyer debts, or buydowns.\nTell me the credit amount you're writing, and I'll confirm it fits before it goes into the offer.",objections:[["Can the seller pay all closing costs?","Normal closing costs can be paid by the seller and don't count toward the 4%."],["Can we do more than 4%?","Concessions above 4% aren't allowed on VA; we can structure normal closing costs separately."]],next:"Run seller credit calc; confirm in writing to agent",compliance:"VA: seller concessions capped at 4% of reasonable value excluding normal closing costs."}),
SP("P76","Referral partners","CPA — tax-season timing for self-employed buyers",{when:"Jan–Apr check-in with a CPA partner",goal:"Coordinate return timing so clients aren't stuck mid-purchase",script:"{{FIRST}}, Steven Shearrill with Patriot Pacific. Quick tax-season idea that helps your clients: if any self-employed client is planning to buy or refinance this spring, a short heads-up helps us both.\nTiming matters — depending on when they apply, lenders may need the newest return, a year-to-date P&L, or proof an extension was filed. If we know early, we can tell them which documents to prioritize so you're not getting a frantic call the week before closing.\nI'm also happy to do a 20-minute lunch-and-learn for your staff on what lenders look for in K-1s, Schedule C, and business returns.",objections:[["I don't want to send you clients","No referral needed — this is about making your clients' loan process smoother if they come to you with questions."],["We're too busy in tax season","Totally — I'll send a one-page cheat sheet instead, and we can do the training in May."]],next:"Send CPA cheat sheet; Zoho tag 'Partner – CPA'; Broker Bridge log",compliance:"RESPA §8: no compensation or thing of value for referrals; education only. Never ask a CPA to alter or 'adjust' figures for qualifying."}),
SP("P77","Referral partners","Divorce attorney / mediator",{when:"Intro meeting with a family-law attorney or mediator",goal:"Be the neutral mortgage resource during settlement",script:"{{FIRST}}, in divorce cases, the house is often the biggest asset — and the mortgage questions come up before the settlement is final. I can help by running neutral scenarios: can one spouse qualify to keep the home and buy out the other, what would an equity buyout look like, and what documentation lenders need from the decree or settlement.\nTwo things that often trip people up: support income usually has to be documented and expected to continue for a period of time, and the settlement language matters for how a buyout is treated. If I see the draft language early, I can flag lending issues before it's signed — I don't give legal advice, but I can tell you what lenders will need.",objections:[["I can't have you pick sides","I won't. I can provide the same factual scenarios to both parties if they both consent."],["We don't refer to lenders","Understood. I can be a resource for questions only — no referral expected."]],next:"Send divorce mortgage checklist; Zoho tag 'Partner – Divorce'; Broker Bridge log",compliance:"No legal or tax advice; neutral scenarios only with borrower consent; RESPA §8 — no thing of value for referrals. Protect confidentiality of both parties."}),
SP("P78","Referral partners","Estate attorney",{when:"Meeting with an estate-planning or probate attorney",goal:"Support trusts, inherited homes, and reverse mortgage education",script:"{{FIRST}}, I see three common mortgage situations in estate work:\n1) Clients with a revocable trust who want to buy or refinance — many lenders can lend to a revocable trust if it meets guidelines; I can review the trust certification.\n2) Heirs inheriting a home with a mortgage — they may need to keep it, refinance, or sell, and I can help them understand options.\n3) Seniors considering a reverse mortgage — I can explain HECM basics and the required HUD counseling so your clients have a clear picture.\nI'm not offering legal advice — just mortgage information to support your work.",objections:[["I don't want clients pressured into reverse mortgages","Neither do I. HECMs require independent HUD counseling, and I encourage family and advisors to be involved."],["Can you speak at our client event?","Yes — education only, no sales pitch."]],next:"Send trust lending checklist; Zoho tag 'Partner – Estate'; Broker Bridge log",compliance:"No legal advice; HECM counseling requirements; RESPA §8 — no thing of value for referrals."}),
SP("P79","Referral partners","Financial advisor",{when:"Coffee meeting with a financial advisor",goal:"Coordinate mortgage strategy with investment planning",script:"{{FIRST}}, I work with advisors when clients ask about buying a home, refinancing, or using equity. I can show options — like keeping investments invested and using a mortgage, or using assets to qualify through asset-depletion programs where appropriate.\nI don't give investment advice; I just provide mortgage numbers so you can make the best recommendation. If a client is considering a HELOC or reverse mortgage, I can provide a clear comparison so you can evaluate it in their overall plan.",objections:[["I don't want clients taking on debt","Understood — I'll show them the full cost and risks so they can decide with you."],["Can you pay us for referrals?","No — that's not allowed under RESPA. We can do joint education events with costs split by actual use."]],next:"Send advisor one-pager; Zoho tag 'Partner – Advisor'; Broker Bridge log",compliance:"No investment or tax advice; RESPA §8 — no referral fees or things of value; co-marketing costs split by actual use."}),
SP("P80","Referral partners","Builder sales office",{when:"Builder rep asks why buyers should use Steven",goal:"Be a strong option while respecting builder incentives",script:"{{FIRST}}, I understand you have a preferred lender, and buyers can choose them for incentives. I'm here as an option for buyers who want a second opinion or VA specialization.\nI'll make it easy for your team: quick pre-approvals, clear communication on timelines, and a VA-ready file that can close on your schedule. I'll also help buyers compare the incentive value against the overall loan pricing so they make an informed choice.",objections:[["Our lender gives buyers incentives","That's great — and buyers can compare. I'll show them the full picture so they decide what's best."],["We only want our lender","Understood. I'm here if buyers ask for another option."]],next:"Send builder timeline sheet; Zoho tag 'Partner – Builder'; Broker Bridge log",compliance:"No disparaging builder lenders; respect consumer choice; RESPA §8 — no thing of value for referrals; disclose any affiliated relationships if applicable."}),
SP("P81","Referral partners","Property manager",{when:"Meeting with a property manager or PM company",goal:"Support investors with financing and timely rent docs",script:"{{FIRST}}, your owners often ask about refinancing or buying more rentals. I can help with DSCR loans and conventional investment financing.\nWhat helps me most: accurate rent rolls and leases when the owner authorizes them. That makes the financing smoother and avoids delays.\nIf you'd like, I can provide a short guide for owners on how lenders use rental income.",objections:[["We can't share owner info","Absolutely — only with the owner's written authorization."],["Do you pay referral fees?","No, that isn't allowed. I'm happy to provide education resources instead."]],next:"Send investor financing guide; Zoho tag 'Partner – PM'; Broker Bridge log",compliance:"Owner authorization required to share data; RESPA §8 — no referral fees or things of value."}),
SP("P82","Referral partners","Insurance agent",{when:"Intro with a home insurance agent",goal:"Coordinate binders and avoid closing delays",script:"{{FIRST}}, insurance is one of the most common closing delays. I'd like to coordinate so clients get binders early and with the correct mortgagee clause and coverage requirements.\nIf you can share your typical turnaround times and requirements, I'll make sure our clients know what to expect. I'm also happy to share our insurance checklist so you know what lenders need.",objections:[["We're slammed","Understood — even a heads-up on timing helps."],["Do you get a referral fee?","No — that's not allowed. This is just coordination."]],next:"Send insurance requirements checklist; Zoho tag 'Partner – Insurance'; Broker Bridge log",compliance:"RESPA §8 — no referral fees; borrowers choose their own insurance provider."}),
SP("P83","Referral partners","Relocation / base housing office",{when:"Meeting with installation relocation or housing office staff",goal:"Offer education resources, respecting base rules",script:"Thank you for meeting with me. I'm Steven Shearrill — retired Navy Chief and a VA mortgage specialist with Patriot Pacific Financial. I understand there are rules on commercial solicitation on base, so I'm here only to offer education if it's helpful.\nI can provide neutral VA homebuying classes or materials, like how BAH can be used as income, what PCS timelines look like, and how VA appraisals work. If you have an approved process for education resources, I'll follow it.",objections:[["We can't endorse lenders","Understood — I'm only offering education, not endorsement."],["We need it to be neutral","Absolutely. I'll provide factual VA information only."]],next:"Send VA education outline; follow installation approval process; Zoho tag 'Partner – Base housing'",compliance:"Follow DoD/installation rules on commercial solicitation; no implied endorsement; education only; RESPA §8 — no thing of value for referrals."}),
SP("P84","Referral partners","Credit counselor (nonprofit)",{when:"Client needs credit help beyond mortgage advice",goal:"Refer to nonprofit counseling without implying credit repair",script:"{{FIRST}}, I'm not a credit repair company, and I can't promise score changes. What I can do is explain what lenders look for and how your report affects qualifying.\nIf you'd like more help, I recommend a nonprofit credit counseling or HUD-approved housing counseling agency. They can help with budgeting and a plan. When you're ready, we'll re-check where you stand.",objections:[["Can you fix my credit?","No — I don't do credit repair. I can show you what lenders look for and refer you to nonprofit counseling."],["How long will it take?","It depends on your situation. A counselor can help you build a plan."]],next:"Provide list of HUD-approved housing counseling agencies; Zoho tag 'Credit counseling referral'; set re-check reminder",compliance:"No credit repair services or score-improvement promises; refer to nonprofit/HUD-approved counseling; no fees for referrals."}),
SP("P85","Military","PCS buyer with orders",{when:"Service member has PCS orders and wants to buy at new duty station",goal:"Build a timeline and confirm occupancy rules",script:"{{FIRST}}, congratulations on the orders. Here's how we make this smooth:\n1) We use your orders and LES to document income and BAH.\n2) VA requires you to occupy within a reasonable time — typically within 60 days, but we'll confirm based on your report date.\n3) We can pre-approve you before you arrive and close remotely if needed.\nI'll build a timeline around your report date and travel plans, and we'll coordinate with your agent.",objections:[["I won't arrive until after closing","That can work if your occupancy timeline meets VA guidelines. We'll document it."],["Can my spouse close for me?","Yes, with a proper POA if needed."]],next:"Create PCS timeline on Handoff Board; collect orders and LES; Zoho tag 'PCS'",compliance:"VA occupancy requirements; verify orders and BAH; no approval guarantees."}),
SP("P86","Military","Deployed spouse POA",{when:"Borrower deploying or unavailable to sign",goal:"Set up POA correctly to avoid closing delays",script:"{{FIRST}}, if you're deploying, we can close with a power of attorney for your spouse or another trusted person. VA and title will need to approve the POA, and it often must be specific to the property and loan.\nLet's get the POA drafted now, before you leave, and we'll confirm it's acceptable with title and underwriting. We may also need an 'alive and well' statement near closing.",objections:[["I already have a general POA","It might work, but many transactions require a specific POA. We'll review it."],["Can my spouse sign everything?","With an approved POA, yes — and spouse occupancy can satisfy VA's occupancy requirement."]],next:"Send POA checklist; coordinate with title; Handoff Board 'POA review'",compliance:"VA and title requirements for POA; occupancy rules; verify identity and authority."}),
SP("P87","Military","BAH qualifying",{when:"Active-duty borrower asks how BAH counts",goal:"Explain BAH and residual income",script:"{{FIRST}}, BAH can be used as income for qualifying, and because it's nontaxable, some programs allow it to be grossed up. We'll use your LES to document base pay, BAH, and other allowances.\nVA also uses residual income — the money left each month after major expenses — to make sure the payment is affordable. If you're within 12 months of ETS, we may need proof of reenlistment or a civilian job offer.",objections:[["Does BAH cover my mortgage?","BAH is just one part of income; we'll look at total income and residual income."],["Do I need a job offer if I'm separating?","If your ETS is within 12 months, we'll need proof of continuance like a reenlistment or job offer."]],next:"Collect LES; run VA residual income calc; Zoho tag 'BAH'",compliance:"Follow VA income and continuance rules; no approval guarantees."}),
SP("P88","Military","VA funding fee exemption (disability)",{when:"Veteran asks about funding fee",goal:"Explain fee and exemption accurately",script:"{{FIRST}}, the VA funding fee depends on your down payment and whether it's first or subsequent use: 2.15% for first use with less than 5% down, 3.30% for subsequent use with less than 5% down, 1.50% with 5–9.99% down, and 1.25% with 10% or more down. IRRRLs are 0.50%.\nYou're exempt if you receive VA disability compensation, and in some other cases. Your COE will show whether you're exempt. If you have a pending claim, let's talk about timing — there may be a refund if your rating is effective before closing.",objections:[["Can I avoid the fee?","Only if you're exempt; otherwise it can be financed or paid in cash."],["My claim is pending","We'll review the timeline. If the rating is awarded with an effective date before closing, you may be eligible for a refund."]],next:"Pull COE; confirm exemption; Zoho tag 'Funding fee exempt'",compliance:"VA funding fee schedule as stated; exemptions per VA; no guarantees on refunds."}),
SP("P89","Military","Second VA loan with remaining entitlement",{when:"Veteran owns a home with a VA loan and wants another",goal:"Explain remaining entitlement and down payment possibilities",script:"{{FIRST}}, if you still have a VA loan, you may have remaining entitlement to buy another home with VA. The calculation depends on the county loan limit and how much entitlement you've used.\nSometimes a down payment is needed, sometimes not. I'll pull your COE and run the entitlement calculation, then show you options with today's pricing, which I'll confirm in writing.\nThe new home must be your primary residence, so this usually fits PCS or a move.",objections:[["Can I keep the first home as a rental?","Yes, if you qualify — we'll account for the payment and any rental income allowed."],["Why would I need a down payment?","Lenders generally want the VA guaranty plus any down payment to cover 25% of the loan amount. If your remaining entitlement falls short of that, a down payment makes up the difference."]],next:"Pull COE; run entitlement calc; Zoho tag 'Second VA'",compliance:"VA entitlement rules; occupancy requirements; no approval guarantees."}),
SP("P90","Military","SCRA protections",{when:"Active-duty borrower asks about SCRA",goal:"Explain basics accurately",script:"{{FIRST}}, the Servicemembers Civil Relief Act provides protections like an interest-rate cap of 6% on certain obligations incurred before active duty, and foreclosure protections during service and for a period after.\nThese protections apply to qualifying debts and situations, so we'd confirm with your servicer and a legal assistance office if you need specifics. I'm happy to help you understand how it may affect a refinance or purchase.",objections:[["Does SCRA lower my mortgage rate now?","It may apply to mortgages taken before active duty. Your servicer can confirm eligibility."],["Can you apply SCRA for me?","The servicer handles SCRA requests; we can help you understand what to provide."]],next:"Provide SCRA resource info; refer to JAG/legal assistance; Zoho tag 'SCRA'",compliance:"Accurate SCRA description; no legal advice; refer to servicer and legal assistance."}),
SP("P91","AI team","Explaining AI-assisted drafts",{when:"Client asks if AI writes messages",goal:"Be transparent about AI use and human review",script:"{{FIRST}}, good question. We use AI tools to help draft messages and summaries so we can respond faster, but Steven and our team review and approve anything that goes to you. Your information is handled under our privacy policy, and we don't let AI make loan decisions.",objections:[["I don't want AI involved","Understood. We can handle your communications without AI drafting."],["Does AI see my documents?","Only as allowed by our privacy policy, and we limit what's shared."]],next:"Note preference in Zoho; adjust Pabbly workflow if client opts out",compliance:"Transparent AI disclosure; human review; privacy and data security (GLBA)."}),
SP("P92","AI team","'Am I talking to a bot?'",{when:"Client asks if they're speaking to an AI",goal:"Be honest and offer a human",script:"Great question, and you deserve a straight answer.\n(If an AI assistant is on the line) Yes — I'm an AI assistant helping Steven's team. I can answer basic questions and schedule time, and I'll connect you to a person anytime you'd like.\n(If a person is on the line) No — I'm {{AGENT}}, a real person on Steven Shearrill's team. We sometimes use AI to help draft messages, but you're talking to me now.",objections:[["I want a real person","Absolutely. I'll connect you with a team member now or schedule a call."],["Why use AI at all?","It helps us respond faster, but people review and make the decisions."]],next:"Route to human if requested; log AI disclosure in Zoho",compliance:"Disclose AI use when applicable (e.g., California bot disclosure law); never claim to be human if AI."}),
SP("P93","AI team","Consent to record/transcribe — CA/FL/IL",{when:"Calls with clients in CA, FL, or IL",goal:"Get explicit consent from all parties",script:"Before we start, {{FIRST}}, I'd like to record and transcribe this call to make sure we capture details accurately. Is that okay with you? If anyone else is on the line, I'll need their consent too.",objections:[["I don't want it recorded","No problem — we won't record. I'll take notes instead."],["Who sees the recording?","Only our team, and it's stored securely per our privacy policy."]],next:"Record only after verbal consent; note consent in Zoho",compliance:"CA, FL, IL require all-party consent; stop recording if consent is withdrawn."}),
SP("P94","AI team","Consent to record — NV/AZ (get consent anyway)",{when:"Calls with clients in NV or AZ",goal:"Use best practice: always ask for consent",script:"{{FIRST}}, I'd like to record and transcribe this call for accuracy. Is that okay? We ask everyone, even where the law may not require it.",objections:[["Why record?","It helps us capture details correctly and serve you better."],["No recording please","Understood — no recording."]],next:"Record only after consent; note in Zoho",compliance:"Best practice: obtain consent from all parties regardless of state; treat Nevada phone calls as all-party consent (Nevada case law); multi-state calls follow the strictest rule."}),
SP("P95","AI team","AI summaries in the file",{when:"Client asks how call notes are stored",goal:"Explain summaries and accuracy checks",script:"{{FIRST}}, we may use AI to summarize calls or emails so our team can follow up quickly. A team member reviews those summaries for accuracy before they're used. If you'd like a copy of your notes or want us to correct anything, just let us know.",objections:[["I don't want AI summaries","No problem — we can do manual notes for your file."],["Is my data safe?","We follow our privacy policy and security practices to protect your information."]],next:"Flag preference in Zoho; adjust workflow if opted out",compliance:"Privacy and data security; human review of AI outputs."}),
SP("P96","Past clients","Reactivation — 2+ years since closing",{when:"Past client closed 2+ years ago",goal:"Reconnect and offer a review",script:"Hi {{FIRST}}, it's Steven Shearrill with Patriot Pacific Financial. It's been a couple of years since we closed your loan, and I wanted to check in. How's everything with the home?\nIf you'd like, I can do a quick mortgage review — equity, payment, and whether any options make sense. No pressure — just making sure you're in a good spot.",objections:[["I'm not looking to refinance","Totally fine — this is just a check-in. I'll keep an eye on things for you."],["Did rates drop?","It depends on your loan. I'll run your numbers and confirm in writing if it helps."]],next:"Annual Mortgage Review invite; Zoho tag 'Reactivation'",compliance:"No rate quotes without disclosures; respect communication preferences."}),
SP("P97","Past clients","Annual Mortgage Review invite",{when:"12 months after closing",goal:"Schedule the annual review",script:"{{FIRST}}, it's time for your Annual Mortgage Review. We'll check your equity, payment, PMI/MIP status, and any goals you have this year. It's a 15-minute call — would {{TIME1}} or {{TIME2}} work?",objections:[["I'm busy","No problem — I can send a quick summary instead."],["Is this a sales call?","It's a review to make sure your mortgage still fits your goals. If nothing makes sense, we'll just confirm that."]],next:"Book Annual Mortgage Review; Zoho tag 'AMR'",compliance:"Approved templates; no rate quotes without disclosures."}),
SP("P98","Past clients","Home anniversary equity call",{when:"Home anniversary",goal:"Share equity snapshot and offer review",script:"Happy home anniversary, {{FIRST}}! I pulled a quick equity snapshot: estimated value {{VALUE}}, balance {{BAL}}, estimated equity {{EQ}}. It's an estimate, but it's a good starting point.\nIf you have goals like home improvements or debt reduction, we can review options. Want to schedule a quick call?",objections:[["How accurate is that value?","It's an estimate; a full appraisal would be more accurate."],["I don't need anything","Great — enjoy the anniversary. I'll check in next year."]],next:"Annual Mortgage Review; Zoho tag 'Anniversary'",compliance:"Value estimates are not appraisals; no promises of equity or approval."}),
SP("P99","Past clients","Review request",{when:"After closing or a positive interaction",goal:"Request an honest review",script:"{{FIRST}}, thank you for trusting us with your loan. If you were happy with the experience, would you be willing to leave an honest review? It helps other families find us. If anything could have been better, I'd love to hear that too.",objections:[["I don't have time","No worries — I'll send a quick link if you change your mind."],["What should I say?","Whatever is true for you — we appreciate honest feedback."]],next:"Send review link; Zoho tag 'Review request'",compliance:"No incentives for reviews; reviews must be honest and not scripted."}),
SP("P100","Past clients","PMI/MIP removal check-in",{when:"Loan is 2–5 years seasoned",goal:"Help client explore PMI/MIP removal",script:"{{FIRST}}, quick check-in: with your payments and home value changes, you might be close to removing PMI. Your servicer handles PMI removal, but we can help you understand the process. If you have FHA MIP, removal depends on your loan's terms, and sometimes refinancing is the only option.\nWant me to help you review it?",objections:[["How do I remove PMI?","Contact your servicer; they'll explain requirements like equity and appraisal."],["Should I refinance?","Only if it provides a benefit. We'll compare options."]],next:"Send PMI removal guide; Annual Mortgage Review flag; Zoho tag 'PMI check'",compliance:"Homeowners Protection Act requirements; no promises of removal; refinance only if beneficial."})
);
